using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithResources();

var app = builder.Build();

app.MapMcp();
app.MapGet("/health", () => "ok");

app.Run();

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpWebService.Tools;

[McpServerToolType]
public static class GreetingTools
{
    [McpServerTool, Description("Generate a personalized greeting message.")]
    public static string Greet(
        [Description("The name of the person to greet")] string name,
        [Description("Optional greeting style: formal or casual")] string style = "casual")
    {
        return style == "formal"
            ? $"Good day, {name}. How may I assist you?"
            : $"Hey {name}! What's up?";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpWebService.Resources;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns current application configuration data.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpWebService",
            Version = "1.0.0",
            MaxConnections = 100,
            Features = new { Logging = true, Caching = true, RateLimiting = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/endpoints", Name = "API Endpoints",
        MimeType = "application/json"),
     Description("Lists available API endpoints and their descriptions.")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Path = "/mcp", Description = "MCP Streamable HTTP endpoint" },
            new { Path = "/health", Description = "Health check" }
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

